head.b:skin:
:root {
    --bg-color: #0b0f19;
    --accent-primary: #00ff66;
    --accent-glow: rgba(0, 255, 102, 0.3);
    --glass-bg: rgba(255, 255, 255, 0.03);
    --glass-border: rgba(255, 255, 255, 0.08);
    --text-main: #f8fafc;
    --text-dim: #94a3b8;
    --card-bg: #111827;
    --header-height: 70px;
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
}

html { scroll-behavior: smooth; }

@keyframes mesh {
    0% { background-position: 0% 0%; }
    100% { background-position: 100% 100%; }
}

body {
    background-color: var(--bg-color);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
    background:
        radial-gradient(circle at 20% 20%, rgba(0, 255, 102, 0.05) 0%, transparent 40%),
        radial-gradient(circle at 80% 80%, rgba(0, 255, 102, 0.05) 0%, transparent 40%),
        #05080f;
    background-attachment: fixed;
}

body::before {
    content: '';
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background:
        radial-gradient(circle at var(--mouse-x, 50%) var(--mouse-y, 50%), rgba(0, 255, 102, 0.12) 0%, transparent 50%),
        url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
    opacity: 0.15;
    pointer-events: none;
    z-index: -1;
}

/* Scanline effect */
body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.1) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.02), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.02));
    background-size: 100% 3px, 3px 100%;
    pointer-events: none;
    z-index: 10000;
}

h1, h2, h3, .logo-text, .orbitron {
    font-family: 'Orbitron', sans-serif;
    letter-spacing: 1px;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

/* --- Header & Navigation --- */
#mainHeader {
    height: var(--header-height);
    background: rgba(11, 15, 25, 0.7);
    backdrop-filter: blur(15px);
    -webkit-backdrop-filter: blur(15px);
    border-bottom: 1px solid var(--glass-border);
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 1000;
    display: flex;
    align-items: center;
    box-shadow: 0 4px 30px rgba(0, 0, 0, 0.3);
}

.header-container {
    width: 92%;
    max-width: 1280px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 700;
    font-size: 1.4rem;
    color: var(--accent-primary);
    text-shadow: 0 0 10px var(--accent-glow);
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 20px;
}

.search-container {
    position: relative;
    display: none; /* Mobile hidden by default */
}

@media (min-width: 768px) {
    .search-container { display: block; }
}

.search-input {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    padding: 8px 15px 8px 35px;
    color: white;
    font-size: 0.9rem;
    width: 200px;
    transition: var(--transition);
}

.search-input:focus {
    width: 280px;
    border-color: var(--accent-primary);
    outline: none;
    box-shadow: 0 0 15px var(--accent-glow);
}

.search-icon {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--text-dim);
    font-size: 0.8rem;
}

.menu-toggle {
    font-size: 1.4rem;
    cursor: pointer;
    color: var(--text-main);
    transition: var(--transition);
}

.menu-toggle:hover { color: var(--accent-primary); }

/* --- Right Drawer Menu --- */
#sideMenu {
    position: fixed;
    top: 0;
    right: 0;
    width: 300px;
    height: 100%;
    background: #0b0f19;
    z-index: 2001;
    padding: 40px 30px;
    transform: translateX(100%);
    transition: transform 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
    border-left: 1px solid var(--accent-primary);
    box-shadow: -10px 0 30px rgba(0,0,0,0.5);
}

#sideMenu.active { transform: translateX(0); }

.close-menu {
    position: absolute;
    top: 20px;
    right: 20px;
    font-size: 1.5rem;
    cursor: pointer;
    color: var(--text-dim);
}

.menu-items {
    list-style: none;
    margin-top: 50px;
}

.menu-items li { margin-bottom: 25px; }

.menu-items a {
    font-size: 1.1rem;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 15px;
    color: var(--text-main);
}

.menu-items a:hover {
    color: var(--accent-primary);
    transform: translateX(10px);
}

.menu-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.5);
    opacity: 0;
    visibility: hidden;
    z-index: 1500;
    transition: var(--transition);
}

.menu-overlay.active {
    opacity: 1;
    visibility: visible;
}

/* --- Main Content --- */
.main-wrapper {
    margin-top: calc(var(--header-height) + 40px);
    min-height: 80vh;
}

.content-container {
    width: 92%;
    max-width: 1200px;
    margin: 0 auto;
}

/* Placeholder styles for other sections */
.section-title {
    margin-bottom: 30px;
    font-size: 1.8rem;
    border-left: 4px solid var(--accent-primary);
    padding-left: 15px;
}

.posts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 30px;
    margin-bottom: 40px;
}

.post-card {
    background: var(--card-bg);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    overflow: hidden;
    transition: var(--transition);
    position: relative;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.post-card:hover {
    transform: translateY(-10px);
    border-color: var(--accent-primary);
    box-shadow: 0 10px 30px rgba(0, 255, 102, 0.1), 0 0 15px var(--accent-glow);
}

.post-card:hover .card-img { transform: scale(1.1); }

.card-img-wrapper {
    width: 100%;
    padding-top: 56.25%; /* 16:9 Aspect Ratio */
    position: relative;
    overflow: hidden;
    background: #1f2937;
}

.card-img {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.card-content {
    padding: 25px;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.post-title {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--text-main);
    margin-bottom: 12px;
    line-height: 1.4;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.post-excerpt {
    font-size: 0.95rem;
    color: var(--text-dim);
    margin-bottom: 20px;
    line-height: 1.6;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.read-more {
    margin-top: auto;
    color: var(--accent-primary);
    font-weight: 600;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 8px;
}

.read-more i { transition: var(--transition); }
.post-card:hover .read-more i { transform: translateX(5px); }

/* --- Post Page --- */
.post-header { margin-bottom: 40px; text-align: center; }
.post-full-title { font-size: 2.5rem; margin-bottom: 20px; color: var(--accent-primary); }
.post-meta { color: var(--text-dim); font-size: 0.9rem; margin-bottom: 20px; }
.post-body { font-size: 1.1rem; line-height: 1.8; color: #cbd5e1; }
.post-body img { max-width: 100%; height: auto; border-radius: 15px; margin: 20px 0; border: 1px solid var(--glass-border); }
.post-body blockquote {
    border-left: 4px solid var(--accent-primary);
    padding: 20px;
    background: var(--glass-bg);
    margin: 30px 0;
    font-style: italic;
    border-radius: 0 10px 10px 0;
}

/* --- Footer --- */
footer {
    background: #05080f;
    padding: 60px 0 30px;
    border-top: 1px solid var(--glass-border);
    margin-top: 80px;
}

.footer-content {
    width: 92%;
    max-width: 1200px;
    margin: 0 auto;
    text-align: center;
}

.footer-links {
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    gap: 20px;
    margin-bottom: 30px;
}

.footer-links a {
    color: var(--text-dim);
    font-size: 0.9rem;
}

.footer-links a:hover { color: var(--accent-primary); }

.copyright {
    color: var(--text-dim);
    font-size: 0.8rem;
    border-top: 1px solid rgba(255,255,255,0.05);
    padding-top: 20px;
}

/* --- Landing Page --- */
#landingPage {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: #05080f;
    z-index: 9999;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    padding: 20px;
    background: radial-gradient(circle at center, #111827 0%, #05080f 100%);
}

.landing-content {
    max-width: 800px;
    animation: fadeIn 1.2s cubic-bezier(0.23, 1, 0.32, 1);
    position: relative;
}

.landing-logo {
    font-size: clamp(2.5rem, 8vw, 4.5rem);
    margin-bottom: 30px;
    color: var(--accent-primary);
    text-shadow: 0 0 20px var(--accent-glow), 0 0 40px var(--accent-glow);
    text-transform: uppercase;
}

.landing-intro {
    font-size: clamp(1rem, 4vw, 1.3rem);
    color: var(--text-main);
    margin-bottom: 50px;
    line-height: 1.8;
    opacity: 0.8;
}

.home-btn {
    display: inline-block;
    background: transparent;
    color: var(--accent-primary);
    padding: 18px 50px;
    border-radius: 4px;
    font-family: 'Orbitron', sans-serif;
    font-weight: 700;
    font-size: 1.2rem;
    border: 2px solid var(--accent-primary);
    cursor: pointer;
    transition: all 0.4s ease;
    text-decoration: none;
    letter-spacing: 2px;
    position: relative;
    overflow: hidden;
}

.home-btn:hover {
    background: var(--accent-primary);
    color: var(--bg-color);
    box-shadow: 0 0 30px var(--accent-glow);
}

.home-btn:hover {
    transform: scale(1.05);
    box-shadow: 0 0 35px var(--accent-glow);
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

/* --- Back to Top --- */
#backToTop {
    position: fixed;
    bottom: 30px;
    right: 30px;
    width: 50px;
    height: 50px;
    background: var(--accent-primary);
    color: var(--bg-color);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 900;
    opacity: 0;
    visibility: hidden;
    transition: var(--transition);
    box-shadow: 0 0 15px var(--accent-glow);
}

#backToTop.show {
    opacity: 1;
    visibility: visible;
}

/* --- Animations --- */
.reveal {
    opacity: 0;
    transform: translateY(30px);
    transition: all 0.8s ease-out;
}

.reveal.active {
    opacity: 1;
    transform: translateY(0);
}

/* Utility */
.hidden { display: none !important; }

body.script:
//
    // Menu Toggle Logic
    const menuOpen = document.getElementById('menuOpen');
    const menuClose = document.getElementById('menuClose');
    const sideMenu = document.getElementById('sideMenu');
    const menuOverlay = document.getElementById('menuOverlay');

    menuOpen.onclick = () => {
        sideMenu.classList.add('active');
        menuOverlay.classList.add('active');
    };

    menuClose.onclick = menuOverlay.onclick = () => {
        sideMenu.classList.remove('active');
        menuOverlay.classList.remove('active');
    };

    document.getElementById('currentYear').textContent = new Date().getFullYear();

    // Back to Top Logic
    const btt = document.getElementById('backToTop');
    window.onscroll = () => {
        if (window.pageYOffset > 300) {
            btt.classList.add('show');
        } else {
            btt.classList.remove('show');
        }
    };
    btt.onclick = () => window.scrollTo(0, 0);

    // Scroll Reveal Logic
    const reveal = () => {
        const reveals = document.querySelectorAll('.post-card, .section-title, .post-header');
        for (let i = 0; i < reveals.length; i++) {
            const windowHeight = window.innerHeight;
            const elementTop = reveals[i].getBoundingClientRect().top;
            const elementVisible = 150;
            if (elementTop < windowHeight - elementVisible) {
                reveals[i].classList.add('active');
            }
        }
    };
    window.addEventListener('scroll', reveal);
    window.addEventListener('load', reveal);

    // Mouse Move Effect
    document.addEventListener('mousemove', e => {
        document.body.style.setProperty('--mouse-x', (e.clientX) + 'px');
        document.body.style.setProperty('--mouse-y', (e.clientY) + 'px');
    });

    // Entry Flow Logic
    (function() {
        const landingPage = document.getElementById('landingPage');
        const mainApp = document.getElementById('mainApp');
        const enterBtn = document.getElementById('enterHome');

        const isHomepage = <b:eval expr='data:view.isHomepage ? "true" : "false"'/>;
        const hasVisited = sessionStorage.getItem('ai_forge_visited');

        if (isHomepage && !hasVisited) {
            landingPage.classList.remove('hidden');
            mainApp.classList.add('hidden');

            enterBtn.onclick = (e) => {
                e.preventDefault();
                sessionStorage.setItem('ai_forge_visited', 'true');
                landingPage.style.opacity = '0';
                landingPage.style.transition = 'opacity 0.5s cubic-bezier(0.4, 0, 0.2, 1)';
                setTimeout(() => {
                    landingPage.classList.add('hidden');
                    mainApp.classList.remove('hidden');
                    window.scrollTo(0, 0);
                }, 500);
            };
        } else {
            mainApp.classList.remove('hidden');
        }
    })();
//
